<script>
(function(){
  var ROOT = document.getElementById('tdx-site');
  if(!ROOT) return;
// Modo estatico (QA): ?static revela tudo sem animacao
const STATIC = location.search.includes('static');

// Header: sombra ao rolar
const header = ROOT.querySelector('.header');
const onScroll = () => header.classList.toggle('scrolled', window.scrollY > 8);
onScroll();
window.addEventListener('scroll', onScroll, { passive: true });

// Menu mobile
const toggle = ROOT.querySelector('#navToggle');
const nav = ROOT.querySelector('#nav');
toggle.addEventListener('click', () => {
  const open = nav.classList.toggle('open');
  toggle.setAttribute('aria-expanded', open);
});
nav.querySelectorAll('a').forEach(a =>
  a.addEventListener('click', () => {
    nav.classList.remove('open');
    toggle.setAttribute('aria-expanded', 'false');
  })
);

// Reveal on scroll
if (STATIC) {
  ROOT.querySelectorAll('.reveal').forEach(el => el.classList.add('in'));
} else {
  const io = new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); }
    });
  }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
  ROOT.querySelectorAll('.reveal').forEach(el => io.observe(el));
}

// Scrollspy: marca o link ativo no nav
const navLinks = [...nav.querySelectorAll('a[href^="#"]')];
const sections = navLinks
  .map(a => ROOT.querySelector(a.getAttribute('href')))
  .filter(Boolean);
const spy = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) {
      const id = '#' + e.target.id;
      navLinks.forEach(a => a.classList.toggle('active', a.getAttribute('href') === id));
    }
  });
}, { rootMargin: '-45% 0px -50% 0px' });
sections.forEach(s => spy.observe(s));

})();
